using System;
using System.IO;
using System.Linq;
using System.Windows;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewDragonScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;VerifyDragonTcp(folder);File.WriteAllText(Path.Combine(folder,"dragon-verification.txt"),"PASS: "+(checks-before)+" checks; real loopback TCP, timer without effects, minimal countdown, authority timeout, selection preservation and Alexstrasza.");}
 void VerifyDragonTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(true);guest.SetFullEffects(false);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Dragon peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Dragon host mulligan");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Dragon opening complete");var g=lanAuthority.Game;long now=0;g.ClockNowMs=()=>now;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}Check(!g.TurnClockEnabled,"Opening has no clock without Nozdormu");var noz=g.Summon(0,"VAN_EX1_560");int fire=Inject(g,"CS2_029");PublishLan();PumpLan(()=>guest.match.TurnClockEnabled,"Countdown reaches guest");TickTurnClock();guest.TickTurnClock();Check(!fullEffects&&minimal==false&&guest.minimal&&turnClockLabel.Text=="15s"&&guest.turnClockLabel.Visibility==Visibility.Visible,"Ordinary effects-off and minimal both display timer");BeginCard(fire);TickTurnClock();Check(pending=="play"&&pendingId==fire,"Timer label update preserves attack/spell selection");int sequence=g.TurnClockSequence;SetFullEffects(true);TickTurnClock();SetFullEffects(false);Check(g.TurnClockSequence==sequence&&g.TurnClockRemainingMs==15000,"Effects settings do not restart or stop timer");Render(Path.Combine(folder,"143-nozdormu-clock-normal.png"));guest.Opacity=1;guest.Render(Path.Combine(folder,"144-nozdormu-clock-minimal.png"));guest.Opacity=0;
  guest.match.LimitTurnClock(3000);var previous=guest.match;PublishLan();PumpLan(()=>!Object.ReferenceEquals(previous,guest.match),"Repeated countdown snapshot received");Check(guest.match.TurnClockRemainingMs<=3000,"Repeated snapshots cannot extend an existing countdown");guest.lanWaiting=true;guest.pending="heroattack";guest.lanPendingRequest=999999;now=15000;TickTurnClock();PumpLan(()=>guest.match.Active==1&&guest.match.Turn==2,"Authority timeout changes turn on both peers");Check(!guest.lanWaiting&&guest.pending==""&&pending==""&&g.Players[0].Hand.Any(h=>h.Id==fire),"Timeout clears stale pending input but preserves unplayed hand");Check(lanAuthority.Revision==3&&g.TurnClockRemainingMs==15000,"Timer advances revision once and resets for next player");guest.DoMatch("power");PumpLan(()=>!guest.lanWaiting&&g.Players[1].Armor==2,"Guest operates normally after automatic turn change");
  g.Silence(new MatchTarget(0,noz.Id));PublishLan();PumpLan(()=>!guest.match.TurnClockEnabled,"Silencing last Nozdormu removes client timer");now+=60000;TickTurnClock();Check(g.Active==1&&g.Turn==2&&!g.TurnClockEnabled,"No source means no automatic switch even past one minute");g.Players[1].Mana=10;g.Players[1].Hand.Clear();g.Players[0].Health=28;g.Players[0].Armor=8;int red=Inject(g,"EX1_561",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==red),"Alexstrasza arrives in guest hand");guest.BeginCard(red);guest.ClickEmptySlot(1,0);Check(guest.pending=="play","Alexstrasza asks hero target after position");guest.ClickMatchTarget(new MatchTarget(0));PumpLan(()=>!guest.lanWaiting&&guest.match.Players[0].Health==15,"Alexstrasza health setting synchronized");Check(g.Players[0].Armor==8&&guest.match.Players[0].Armor==8&&g.HeroHealthLimit(0)==30,"Health setting preserves armor and hero health limit");guest.ApplyMode(false);guest.Opacity=1;guest.Render(Path.Combine(folder,"145-alexstrasza-health-codex.png"));guest.Opacity=0;
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
